var a=`0852-pakora`;var n=`world-0852`;var s=`IN`;var t=`south-asia`;var o=8;var r=41;var l={en:`Pakora`,ua:`Пакора`};var d={en:`Pakora is a India dish made with yellow onion, spinach, serrano pepper, besan (gram flour). This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Пакора, страва кухні країни Індія. Основні складники: жовта цибуля, шпинат, перець серрано, бесан (нутове борошно). Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var g=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:12,i:[[`yellow-onion`,240,`g`],[`spinach`,200,`g`],[`serrano-pepper`,2,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`besan-gram-flour`,250,`g`],[`water`,165,`ml`],[`ajwain-seeds`,4,`g`],[`ground-turmeric`,3,`g`],[`table-salt`,null,`to_taste`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 18 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 18 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:18,i:[[`canola-oil`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`chaat-masala`,5,`g`]]}];var h={slug:a,id:n,country:`IN`,region:t,servings:8,minutes:41,title:l,text:d,steps:g};export{s as country,h as default,n as id,r as minutes,t as region,o as servings,a as slug,g as steps,d as text,l as title};